// === sf-modbus-driver v10: MBAP+PDU + 字节序 + 模拟模式 ===
var net = global.get('net');
var SIM_MODE = global.get('edge_simulationMode') || false;
var DEBUG = global.get('edge_debug') || false;

var dev = msg.payload;
if (!dev || !dev.id) {
    node.warn('[MB-Driver] Invalid input, missing device id');
    return null;
}

// === Singleton lock (60s expiry) ===
var lock = global.get('edge_modbus_driver_lock');
if (lock && (Date.now() - lock.ts < 60000) && lock.instanceId !== node.id) {
    if (DEBUG) node.warn('[MB-Driver] Another instance running, requeue');
    setTimeout(function () { node.send(msg); }, 200);
    return null;
}
global.set('edge_modbus_driver_lock', { ts: Date.now(), instanceId: node.id });

var pp = dev.protocolParams || {};
var roundStart = Date.now();
var slaveId = pp.slaveId || 1;
var funcCode = pp.functionCode || 3;
var byteOrder = pp.byteOrder || 'ABCD';

// === Simulation Mode ===
if (SIM_MODE || !net) {
    setTimeout(function () {
        var simData = {};
        (dev.tags || []).forEach(function (t) {
            simData[t.id] = {
                rawValue: (t.dataType === 'BOOL') ? (Math.random() > 0.5 ? 1 : 0)
                    : Math.floor(Math.random() * 65535) - 32768,
                quality: 0,
                ts: new Date().toISOString()
            };
        });
        var ok = Math.random() > 0.1;
        msg.payload = {
            deviceId: dev.id,
            deviceName: dev.deviceName,
            success: ok,
            data: simData,
            error: ok ? null : 'Simulated timeout',
            driverType: 'driver-modbus-tcp',
            plcIp: dev.plcIp,
            plcPort: dev.plcPort,
            roundTimeMs: Date.now() - roundStart
        };
        node.status({
            fill: ok ? 'green' : 'red',
            shape: 'dot',
            text: dev.deviceName + ' SIM ' + (ok ? 'OK' : 'FAIL')
        });
        node.send(msg);
        global.set('edge_modbus_driver_lock', null);
    }, 10 + Math.random() * 30);
    return null;
}

// ===== Real TCP Mode =====

// Step 1: Group tags by register type (function code grouping)
var tags = dev.tags || [];
if (tags.length === 0) {
    msg.payload = {
        deviceId: dev.id, deviceName: dev.deviceName,
        success: false, data: {}, error: 'No tags',
        driverType: 'driver-modbus-tcp', plcIp: dev.plcIp, plcPort: dev.plcPort,
        roundTimeMs: Date.now() - roundStart
    };
    global.set('edge_modbus_driver_lock', null);
    node.send(msg);
    return null;
}

// Cluster by address proximity (gap <= 20, max 125 registers per Modbus spec)
var sorted = tags.slice().sort(function (a, b) { return a.addr - b.addr; });
var groups = [];
var cluster = [sorted[0]];
var MAX_GAP = 20;
var MAX_REGS = 125;
for (var i = 1; i < sorted.length; i++) {
    var gap = sorted[i].addr - cluster[cluster.length - 1].addr;
    if (gap <= MAX_GAP && cluster.length < MAX_REGS) {
        cluster.push(sorted[i]);
    } else {
        groups.push(cluster);
        cluster = [sorted[i]];
    }
}
if (cluster.length > 0) groups.push(cluster);

if (DEBUG) node.warn('[MB-Driver] ' + dev.deviceName + ' groups=' + groups.length + ' slaveId=' + slaveId + ' byteOrder=' + byteOrder);

// Byte order helpers — reorder 4 bytes from 2 consecutive registers
function reorderBytes(r0_hi, r0_lo, r1_hi, r1_lo, order) {
    var b; // 4-byte array
    switch (order) {
        case 'BADC': b = [r0_lo, r0_hi, r1_lo, r1_hi]; break;
        case 'CDAB': b = [r1_hi, r1_lo, r0_hi, r0_lo]; break;
        case 'DCBA': b = [r1_lo, r1_hi, r0_lo, r0_hi]; break;
        default:     b = [r0_hi, r0_lo, r1_hi, r1_lo]; break; // ABCD
    }
    return Buffer.from(b);
}

function read16(hi, lo, order, signed) {
    var val;
    if (order === 'BADC' || order === 'DCBA') {
        val = (lo << 8) | hi;
    } else {
        val = (hi << 8) | lo;
    }
    if (signed && val > 32767) val = val - 65536;
    return val;
}

// Step 2: Build Modbus TCP frame
function buildModbusFrame(transactionId, unitId, startAddr, count) {
    var buf = Buffer.alloc(12);
    buf.writeUInt16BE(transactionId, 0);
    buf.writeUInt16BE(0, 2);           // Protocol ID
    buf.writeUInt16BE(6, 4);           // Length (remainder)
    buf[6] = slaveId;                   // Unit ID
    buf[7] = funcCode;                 // Function code
    buf.writeUInt16BE(startAddr, 8);   // Start address
    buf.writeUInt16BE(count, 10);      // Quantity
    return buf;
}

// Step 3: Parse Modbus response
function parseModbusResponse(buf, startAddr, count) {
    if (!buf || buf.length < 9) return null;
    var respFuncCode = buf[7];
    if (respFuncCode > 0x80) {
        return { error: 'Modbus exception ' + buf[8] };
    }
    var byteCount = buf[8];
    if (buf.length < 9 + byteCount) return null;
    var result = {};
    if (funcCode === 1 || funcCode === 2) {
        // Bit data: 1 byte = 8 bits (coils / discrete inputs)
        for (var i = 0; i < count; i++) {
            var byteIdx = 9 + Math.floor(i / 8);
            var bitIdx = i % 8;
            if (byteIdx >= buf.length) break;
            result['R' + (startAddr + i)] = { hi: 0, lo: (buf[byteIdx] >> bitIdx) & 1, isBit: true };
        }
    } else {
        // Register data: 2 bytes per register (03/04)
        for (var i = 0; i < count; i++) {
            var offset = 9 + i * 2;
            if (offset + 1 >= buf.length) break;
            result['R' + (startAddr + i)] = { hi: buf[offset], lo: buf[offset + 1] };
        }
    }
    return { values: result };
}

// Step 4: Process groups sequentially
var allStdData = {};
var hasFailed = false;
var firstError = '';
var timeout = dev.timeout || 3000;
var maxRetries = dev.maxRetries || 2;
var retryInterval = dev.retryInterval || 300;
var txnId = Math.floor(Math.random() * 65535);

function processGroup(gi) {
    if (gi >= groups.length) {
        var roundTimeMs = Date.now() - roundStart;
        msg.payload = {
            deviceId: dev.id,
            deviceName: dev.deviceName,
            success: !hasFailed,
            data: allStdData,
            error: hasFailed ? firstError : null,
            driverType: 'driver-modbus-tcp',
            plcIp: dev.plcIp,
            plcPort: dev.plcPort,
            roundTimeMs: roundTimeMs
        };
        node.status({
            fill: hasFailed ? 'red' : 'green',
            shape: 'dot',
            text: dev.deviceName + ' ' + Object.keys(allStdData).length + ' vals'
        });
        global.set('edge_modbus_driver_lock', null);
        node.send(msg);
        return;
    }

    var grp = groups[gi];
    var addrs = grp.map(function (t) { return t.addr; });
    var startA = addrs[0];
    var maxAddr = addrs[addrs.length - 1];
    // Expand range for 32-bit tags that need 2 registers
    grp.forEach(function (t) {
        var dt = t.dataType || 'INT16';
        if ((dt === 'FLOAT32' || dt === 'INT32' || dt === 'UINT32') && t.addr + 1 > maxAddr) {
            maxAddr = t.addr + 1;
        }
    });
    var wordCount = maxAddr - startA + 1;

    function attemptGroup(attempt) {
        if (attempt > maxRetries) {
            hasFailed = true;
            if (!firstError) firstError = 'Modbus read failed at addr ' + startA;
            setTimeout(function () { processGroup(gi + 1); }, 0);
            return;
        }

        var client = new net.Socket();
        var buf = Buffer.alloc(0);
        var resolved = false;

        client.setTimeout(timeout);

        var currentTxnId = (txnId + 1) & 0xFFFF;
        txnId = currentTxnId;
        client.connect(dev.plcPort, dev.plcIp, function () {
            var frame = buildModbusFrame(currentTxnId, slaveId, startA, wordCount);
            client.write(frame);
        });

        client.on('data', function (chunk) {
            buf = Buffer.concat([buf, chunk]);
            // Modbus TCP: MBAP header (6 bytes) + PDU
            if (!resolved && buf.length >= 7) {
                var mbapLen = buf.readUInt16BE(4);
                var expectedTotal = 6 + mbapLen;
                if (buf.length < expectedTotal) return;
                // Validate Transaction ID + Unit ID
                var respTxnId = buf.readUInt16BE(0);
                var respUnitId = buf[6];
                if (respTxnId !== currentTxnId || respUnitId !== slaveId) {
                    if (DEBUG) node.warn('[MB-Driver] TxnId/UnitId mismatch: exp ' + currentTxnId + '/' + slaveId + ' got ' + respTxnId + '/' + respUnitId);
                    buf = Buffer.alloc(0);  // Discard and wait for correct frame
                    return;
                }
                if (buf.length < 9) return;
                var byteCount = buf[8];
                if (buf.length >= expectedTotal) {
                    resolved = true;
                    var parsed = parseModbusResponse(buf, startA, wordCount);
                    if (parsed && parsed.values) {
                        grp.forEach(function (t) {
                            var key = 'R' + t.addr;
                            var reg = parsed.values[key];
                            var rv, q = 0;
                            if (!reg || reg.hi === undefined) { q = 2; rv = null; }
                            else if (reg.isBit) {
                                rv = reg.lo;  // Bit value, no byte order transformation
                            } else {
                                var dt = t.dataType || 'INT16';
                                if (dt === 'FLOAT32' || dt === 'INT32' || dt === 'UINT32') {
                                    var reg2 = parsed.values['R' + (t.addr + 1)];
                                    if (!reg2) { q = 2; rv = null; }
                                    else {
                                        var b4 = reorderBytes(reg.hi, reg.lo, reg2.hi, reg2.lo, byteOrder);
                                        if (dt === 'FLOAT32') rv = parseFloat(b4.readFloatBE(0).toFixed(4));
                                        else if (dt === 'UINT32') rv = b4.readUInt32BE(0);
                                        else rv = b4.readInt32BE(0);
                                    }
                                } else if (dt === 'UINT16') {
                                    rv = read16(reg.hi, reg.lo, byteOrder, false);
                                } else {
                                    rv = read16(reg.hi, reg.lo, byteOrder, true);
                                }
                            }
                            allStdData[t.id] = {
                                rawValue: rv,
                                quality: q,
                                ts: new Date().toISOString()
                            };
                        });
                        try { client.destroy(); } catch (e) {}
                        setTimeout(function () { processGroup(gi + 1); }, 0);
                    } else if (parsed && parsed.error) {
                        hasFailed = true;
                        if (!firstError) firstError = parsed.error;
                        try { client.destroy(); } catch (e) {}
                        setTimeout(function () { processGroup(gi + 1); }, 0);
                    } else {
                        try { client.destroy(); } catch (e) {}
                        setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
                    }
                }
            }
        });

        client.on('timeout', function () {
            if (resolved) return;
            resolved = true;
            try { client.destroy(); } catch (e) {}
            setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
        });

        client.on('error', function (e) {
            if (resolved) return;
            resolved = true;
            try { client.destroy(); } catch (e2) {}
            setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
        });

        client.on('close', function () {
            if (!resolved) {
                resolved = true;
                if (buf.length === 0) {
                    hasFailed = true;
                    if (!firstError) firstError = 'TCP closed (no data)';
                    setTimeout(function () { processGroup(gi + 1); }, 0);
                } else {
                    try { client.destroy(); } catch (e) {}
                    setTimeout(function () { attemptGroup(attempt + 1); }, retryInterval);
                }
            }
        });
    }

    attemptGroup(0);
}

try {
    processGroup(0);
} catch (e) {
    node.error('[MB-Driver] Exception: ' + e.message);
    global.set("edge_modbus_driver_lock", null);
}
return null;
